import{_t as e,it as t,n,rt as r}from"./chunks/framework.gd_RGE3V.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireGlu Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireGlu/aireglu-v1-125-0.md","filePath":"aireblock-releases/AireGlu/aireglu-v1-125-0.md","lastUpdated":1793188062000}`),a={name:`aireblock-releases/AireGlu/aireglu-v1-125-0.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="aireglu-release-notes" tabindex="-1"><span class="fsc-product"><img src="/aireglu-icon.png"> AireGlu Release Notes</span> <a class="header-anchor" href="#aireglu-release-notes" aria-label="Permalink to “AireGlu Release Notes”">​</a></h1><blockquote><p><strong>Version:</strong> 1.125.0<br><strong>Release Date:</strong> 4th November 2026</p></blockquote><h2 id="summary-of-changes" tabindex="-1">Summary of Changes <a class="header-anchor" href="#summary-of-changes" aria-label="Permalink to “Summary of Changes”">​</a></h2><h4 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h4><ul><li>Edit Repository URL, Branch and Credentials (GLU-3320)</li></ul><h4 id="⚡-improvements" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements" aria-label="Permalink to “⚡ Improvements”">​</a></h4><ul><li>More Resilient Database Connections (GLU-3326)</li><li>Clearer Responses When Permissions Are Missing (GLU-3296)</li></ul><h4 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h4><ul><li>Formatted Input for Endpoint Exceptions in Usage Data (GLU-3309)</li><li>Copied MCP Client Config Now Supports Delegate Exchange (GLU-3321)</li></ul><h3 id="⚠️-upgrade-notes" tabindex="-1">⚠️ Upgrade Notes <a class="header-anchor" href="#⚠️-upgrade-notes" aria-label="Permalink to “⚠️ Upgrade Notes”">​</a></h3><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><ul><li><strong>MCP client configs copied before this release</strong> need updating by hand. Change the scope in the copied config to <code>AireGluMcp delegate_exchange</code>, clear the cached mcp-remote token (in <code>~/.mcp-auth</code>) and reconnect to sign in again. Configs copied after the upgrade are correct automatically.</li><li><strong>Endpoints secured with an OIDC auth context</strong> now return <strong>403 Forbidden</strong>, rather than 401 Unauthorized, when the caller&#39;s token is valid but lacks a required permission. Any integration or test that expects a 401 in this situation should be updated.</li></ul></div><h1 id="detailed-changes" tabindex="-1">Detailed Changes <a class="header-anchor" href="#detailed-changes" aria-label="Permalink to “Detailed Changes”">​</a></h1><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><hr><h4 id="edit-repository-url-branch-and-credentials-glu-3320" tabindex="-1">Edit Repository URL, Branch and Credentials (GLU-3320) <a class="header-anchor" href="#edit-repository-url-branch-and-credentials-glu-3320" aria-label="Permalink to “Edit Repository URL, Branch and Credentials (GLU-3320)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The repository edit dialogue (now titled &quot;Edit Repository&quot;) lets you change the repository URL, branch and authentication mode. Changes are previewed first, showing which endpoints and MCP servers would be added, removed or kept, along with any conflicts, before being approved. If the import fails on approval, nothing changes and existing endpoints keep working. Stored credentials are kept if left blank, and only need re-entering when the authentication mode or username changes.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can now point an existing repository at a different location or branch without deleting and recreating it. You&#39;ll see exactly what will change before anything is saved, and your live endpoints stay safe if something goes wrong.</p></div><h3 id="⚡-improvements-1" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-1" aria-label="Permalink to “⚡ Improvements”">​</a></h3><hr><h4 id="more-resilient-database-connections-glu-3326" tabindex="-1">More Resilient Database Connections (GLU-3326) <a class="header-anchor" href="#more-resilient-database-connections-glu-3326" aria-label="Permalink to “More Resilient Database Connections (GLU-3326)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Runtime lookups made before an endpoint runs, such as secrets, variables, users, repositories and permissions, no longer drop their database connection when the caller cancels or times out. These lookups now use their own short timeout, frequently used data is cached, and repository endpoint lookups query only the matching endpoint. Requests cancelled by the caller are now logged as client cancellations (status 499) instead of server errors.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>AireGlu stays fast and stable when other systems give up on requests early, such as when a user is typing in a form. This protects performance across the AireSuite products that share the same infrastructure.</p></div><h4 id="clearer-responses-when-permissions-are-missing-glu-3296" tabindex="-1">Clearer Responses When Permissions Are Missing (GLU-3296) <a class="header-anchor" href="#clearer-responses-when-permissions-are-missing-glu-3296" aria-label="Permalink to “Clearer Responses When Permissions Are Missing (GLU-3296)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Endpoints secured with an OIDC auth context now return 403 Forbidden when the caller&#39;s token is valid but does not hold a required permission, in line with the OAuth standard. Missing, invalid or unverifiable tokens still return 401 Unauthorized. This applies to both standard and async batch endpoint calls.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>When a call is refused, you can now tell straight away whether the problem is with signing in or with the permissions granted to that user, making access issues quicker to diagnose.</p></div><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><hr><h4 id="formatted-input-for-endpoint-exceptions-in-usage-data-glu-3309" tabindex="-1">Formatted Input for Endpoint Exceptions in Usage Data (GLU-3309) <a class="header-anchor" href="#formatted-input-for-endpoint-exceptions-in-usage-data-glu-3309" aria-label="Permalink to “Formatted Input for Endpoint Exceptions in Usage Data (GLU-3309)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixed an issue in Metrics → Usage Data where the Formatted Input panel for Endpoint Exception entries showed the request body as raw text. These entries are now formatted and highlighted in the same way as other entries (for example JSON or XML).</p></div><h4 id="copied-mcp-client-config-now-supports-delegate-exchange-glu-3321" tabindex="-1">Copied MCP Client Config Now Supports Delegate Exchange (GLU-3321) <a class="header-anchor" href="#copied-mcp-client-config-now-supports-delegate-exchange-glu-3321" aria-label="Permalink to “Copied MCP Client Config Now Supports Delegate Exchange (GLU-3321)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixed an issue where the &quot;copy client config&quot; option in AI Tools did not include the <code>delegate_exchange</code> scope, so tools using a Delegate Exchange connection failed. The copied config now requests <code>AireGluMcp delegate_exchange</code>. Configs copied before this release need updating by hand (see Upgrade Notes).</p></div>`,31)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};